#!/usr/bin/env python3
"""Classify documents in /app/documents as invoice/other, move them, and
summarise invoice totals into /app/invoices/summary.csv.

Text extraction uses public CLI tools (pdftotext, tesseract) so it works
regardless of installed python library versions.
"""
import csv
import os
import re
import shutil
import subprocess
import sys

SRC = "/app/documents"
INV = "/app/invoices"
OTHER = "/app/other"

MONEY = re.compile(r"\d[\d  .,]*\d|\d")


def extract_text(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == ".pdf":
        out = subprocess.run(["pdftotext", "-layout", path, "-"],
                             capture_output=True, text=True)
        text = out.stdout
        if text.strip():
            return text
        # scanned pdf -> rasterise then OCR
        subprocess.run(["pdftoppm", "-r", "300", "-png", path, "/tmp/_pg"],
                       capture_output=True)
        chunks = []
        for f in sorted(os.listdir("/tmp")):
            if f.startswith("_pg") and f.endswith(".png"):
                chunks.append(ocr(os.path.join("/tmp", f)))
                os.remove(os.path.join("/tmp", f))
        return "\n".join(chunks)
    return ocr(path)


def ocr(path):
    out = subprocess.run(
        ["tesseract", path, "-", "--psm", "6",
         "-c", "preserve_interword_spaces=1"],
        capture_output=True, text=True)
    return out.stdout


def to_number(tok):
    t = tok.strip().replace(" ", " ")
    t = re.sub(r"[^\d.,]", "", t.replace(" ", ""))
    if not t:
        return None
    if "," in t and "." in t:
        if t.rfind(",") > t.rfind("."):        # 1.234,56
            t = t.replace(".", "").replace(",", ".")
        else:                                   # 1,234.56
            t = t.replace(",", "")
    elif "," in t:
        frac = t.rsplit(",", 1)[1]
        t = t.replace(",", ".") if len(frac) != 3 else t.replace(",", "")
    try:
        return float(t)
    except ValueError:
        return None


def numbers_in(line):
    vals = []
    for m in MONEY.finditer(line):
        v = to_number(m.group())
        if v is not None:
            vals.append(v)
    return vals


def is_invoice(text):
    low = text.lower()
    if re.search(r"\binvoice\b", low):
        return True
    return False


TOTAL_KEYS = [
    (re.compile(r"\bgrand\s*total\b", re.I), 3),
    (re.compile(r"\btotal\s*price\b|\btotalprice\b", re.I), 2),
    (re.compile(r"\btotal\b", re.I), 2),
    (re.compile(r"\bamount\s*due\b|\bbalance\s*due\b", re.I), 1),
]
SKIP = re.compile(r"sub\s*total|subtotal|net\s*worth\s*$|vat\s*\[%\]", re.I)
VAT_KEY = re.compile(r"\b(vat|gst|sales\s*tax|tax)\b", re.I)
TAX_ID = re.compile(r"\btax\s*(id|number|no)\b", re.I)


def extract_amounts(text):
    lines = [l.rstrip() for l in text.splitlines()]
    best = None          # (priority, total, vat)
    for line in lines:
        if not line.strip() or SKIP.search(line):
            continue
        for pat, prio in TOTAL_KEYS:
            if not pat.search(line):
                continue
            nums = numbers_in(re.sub(r"\d+\s*%", " ", line))
            nums = [n for n in nums if n > 0]
            if not nums:
                continue
            if len(nums) >= 3:
                total, vat = nums[-1], nums[-2]
            else:
                total, vat = nums[-1], None
            if best is None or prio > best[0]:
                best = (prio, total, vat)
            break
    if best is None:
        return None, 0
    total, vat = best[1], best[2]
    if vat is None:
        vat = find_vat(lines)
    return total, vat if vat is not None else 0


def find_vat(lines):
    for line in lines:
        if TAX_ID.search(line) or not VAT_KEY.search(line):
            continue
        nums = numbers_in(re.sub(r"\d+\s*%", " ", line))
        nums = [n for n in nums if n > 0]
        if len(nums) == 1:
            return nums[0]
    return 0


def fmt(v):
    return f"{v:.2f}"


def main():
    os.makedirs(INV, exist_ok=True)
    os.makedirs(OTHER, exist_ok=True)
    rows = []
    for name in sorted(os.listdir(SRC)):
        path = os.path.join(SRC, name)
        if not os.path.isfile(path):
            continue
        text = extract_text(path)
        if is_invoice(text):
            total, vat = extract_amounts(text)
            shutil.move(path, os.path.join(INV, name))
            rows.append((name, total or 0.0, vat or 0.0))
            print(f"invoice {name}: total={total} vat={vat}", file=sys.stderr)
        else:
            shutil.move(path, os.path.join(OTHER, name))
            print(f"other   {name}", file=sys.stderr)

    with open(os.path.join(INV, "summary.csv"), "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["filename", "total_amount", "vat_amount"])
        for name, total, vat in rows:
            w.writerow([name, fmt(total), fmt(vat)])
        w.writerow(["total", fmt(sum(r[1] for r in rows)),
                    fmt(sum(r[2] for r in rows))])


if __name__ == "__main__":
    main()
